<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Students</title><style>body{font-family:Arial;background:#f5f7fb;margin:0;color:#1f2937}.wrap{max-width:1250px;margin:auto;padding:25px}.bar{display:flex;justify-content:space-between}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-top:18px}input,button,.btn{padding:9px;border-radius:7px;border:1px solid #d0d5dd}.btn,button{background:#111827;color:#fff;text-decoration:none}.primary{background:#2563eb}.danger{background:#dc2626}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{padding:9px;border-bottom:1px solid #eee;text-align:left}.ok{color:#15803d}.actions{display:flex;gap:5px}.muted{color:#667085}</style></head><body><div class="wrap"><div class="bar"><div><h1>{{ $status===0 ? 'Pending Students' : ($status===2 ? 'Blocked Students' : 'Active Students') }}</h1><div class="muted">Student management</div></div><a class="btn" href="{{ route('admin.dashboard') }}">Dashboard</a></div>@if(session('success'))<div class="card ok">{{session('success')}}</div>@endif<div class="card"><form method="GET"><input name="search" placeholder="Name, ID, phone, WhatsApp, email, language" value="{{request('search')}}"> <input name="student_no" placeholder="Student ID" value="{{request('student_no')}}"> <input name="refer_no" placeholder="Refer ID" value="{{request('refer_no')}}"><select name="status"><option value="1" @selected($status===1)>Active</option><option value="0" @selected($status===0)>Pending</option><option value="2" @selected($status===2)>Blocked</option></select> <button class="primary">Search</button></form><table><thead><tr><th>No</th><th>Name</th><th>WhatsApp</th><th>Point</th><th>Refer By</th><th>Trainer</th><th>Activated</th><th>Join</th><th>Counsellor</th><th>Point</th><th>Action</th></tr></thead><tbody>@forelse($students as $s)<tr><td>{{$s->student_no}}</td><td>{{$s->student_name}}</td><td>{{