utton class="primary">Activate</button></form>@endif<a class="btn primary" href="{{route('admin.students.edit',$s->id)}}">Edit</a><form method="POST" action="{{route('admin.students.block',$s->id)}}" onsubmit="return confirm('Block this student?')">@csrf<button class="danger">Block</button></form></div></td></tr>@empty<tr><td colspan="11">No students found.</td></tr>@endforelse</tbody></table>{{$students->links()}}</div></div></body></html>